// ── Традиции вдоль цепочки ────────────────────────────────────
// Переход есть тогда и только тогда, когда у двух философов НЕТ НИ
// ОДНОЙ общей традиции — тот же критерий, что в режиме
// between_traditions, чтобы одно слово не значило в двух местах разного.
// Никакой «главной традиции» не выбирается: порядка среди традиций нет,
// и всякое «главное» было бы выдумкой. Замер: на 955 межфилософских
// рёбер общих традиций нет у 648, ровно одна у 293, две у 14 (все —
// Локк и Юм: эмпиризм и Просвещение).
function traditionsOfPhilosopher(name) {
  return (philosopherTraditions[name] || [])
    .map(id => (traditions.find(t => t.id === id) || {}).name)
    .filter(Boolean);
}

function analyzePathTraditions(pathNodes) {
  const segments = [];
  for (let i = 0; i < pathNodes.length - 1; i++) {
    const a = pathNodes[i].concept, b = pathNodes[i + 1].concept;
    if (a === b) { segments.push({ kind: 'internal' }); continue; }
    const ta = philosopherTraditions[a] || [], tb = philosopherTraditions[b] || [];
    const shared = ta.filter(x => tb.includes(x));
    segments.push(shared.length
      ? { kind: 'shared', shared: shared.map(id =>
          (traditions.find(t => t.id === id) || {}).name).filter(Boolean) }
      : { kind: 'crossing', from: traditionsOfPhilosopher(a),
          to: traditionsOfPhilosopher(b) });
  }
  // Различных традиций и переходов считаем ПОРОЗНЬ: цепочка может выйти
  // из традиции и вернуться в неё, и слитный счёт тогда солгал бы.
  const distinct = new Set();
  pathNodes.forEach(n => (philosopherTraditions[n.concept] || [])
    .forEach(id => distinct.add(id)));
  return { segments, crossings: segments.filter(s => s.kind === 'crossing').length,
           distinct: distinct.size };
}

